import{_ as d,C as r,o as a,c as i,a2 as o,E as n}from"./chunks/framework.DCaeQ2Kp.js";const b=JSON.parse('{"title":"总体架构","description":"","frontmatter":{},"headers":[],"relativePath":"guide/architecture.md","filePath":"guide/architecture.md"}'),c={name:"guide/architecture.md"};function s(l,t,m,h,u,g){const e=r("DiagramFrame");return a(),i("div",null,[t[0]||(t[0]=o('<h1 id="总体架构" tabindex="-1">总体架构 <a class="header-anchor" href="#总体架构" aria-label="Permalink to &quot;总体架构&quot;">​</a></h1><p>三段式：<strong>交互端</strong>（渲染 + 音频 IO）— <strong>编排器</strong>（回合/打断/路由/状态机）— <strong>模型服务</strong>（LLM/ASR/TTS）。进程间走 <code>momo-ws v1</code> 与 OpenAI-compatible HTTP；<strong>运维面</strong>（momoctl + Web 控制台）在旁路，不在数据通路上。</p>',2)),n(e,{src:"system-main.html",height:720}),t[1]||(t[1]=o('<h2 id="组件职责" tabindex="-1">组件职责 <a class="header-anchor" href="#组件职责" aria-label="Permalink to &quot;组件职责&quot;">​</a></h2><table tabindex="0"><thead><tr><th>组件</th><th>仓库</th><th>语言</th><th>职责</th><th>对外接口</th></tr></thead><tbody><tr><td>交互端</td><td>momo-app</td><td>TS</td><td>Live2D 渲染、表情/口型、麦采集、播放、文字输入</td><td>WS 客户端 → <code>/ws/ui</code></td></tr><tr><td>编排器 momod</td><td>momo-app</td><td>Rust</td><td>WS 服务、回合状态机、barge-in、句切、历史、路由</td><td>监听 <code>:7800</code></td></tr><tr><td>ASR 服务</td><td>momo-models</td><td>Python</td><td>silero-vad 分段 + SenseVoice 转写（纯 CPU，实测 RTF 0.040）</td><td>WS 服务 <code>:7810</code></td></tr><tr><td>TTS 服务</td><td>momo-models</td><td>Python</td><td>逐句合成 + 情感参数，audio.chunk 回流</td><td>WS 服务 <code>:7811</code></td></tr><tr><td>大脑</td><td>外部</td><td>—</td><td>OpenAI-compatible 流式 chat</td><td>HTTP <code>:7820</code> / 远端</td></tr><tr><td>action 提供方</td><td>第三方</td><td>任意</td><td>注册/执行 action（P4）</td><td>WS 客户端 → <code>/ws/action</code></td></tr><tr><td>momoctl</td><td>momo-infra</td><td>Rust</td><td>doctor、模型管理、编排启停、训练 job、Web 控制台</td><td>env / CLI / REST</td></tr></tbody></table><h2 id="数据流" tabindex="-1">数据流 <a class="header-anchor" href="#数据流" aria-label="Permalink to &quot;数据流&quot;">​</a></h2><p><strong>语音回合（主路径）</strong>——详见<a href="/momo/guide/protocol">协议时序图</a>：</p><ol><li>前端麦 PCM → 二进制 <code>audio.chunk</code> → 编排器 → 转发 ASR</li><li>ASR：silero-vad 分段 + SenseVoice 转写 → <code>input.audio.segment</code>（含 text/lang）回编排器</li><li>编排器建回合、组装历史+人设 → OpenAI SSE 调大脑</li><li>token 流 → 句切 + 剥 <code>[emotion]</code> tag → <code>output.sentence</code> 双发（前端字幕/表情 + TTS）</li><li>TTS 逐句合成 → <code>audio.chunk</code> → 前端边下边播</li><li>中途用户开口 → <code>control.barge_in</code> 三动作（见<a href="/momo/guide/barge-in">打断</a>）</li></ol><p><strong>训练/产物通路（离线）</strong>：4090D ≤24h 训练 → 产物回传 → 登记 MANIFEST → env 切换激活。不进入运行时数据流。</p><h2 id="关键决策-摘自-adr" tabindex="-1">关键决策（摘自 ADR） <a class="header-anchor" href="#关键决策-摘自-adr" aria-label="Permalink to &quot;关键决策（摘自 ADR）&quot;">​</a></h2><ul><li><strong>LLM 不进 momo-ws</strong>（ADR-006）：流式取消=直接 abort HTTP；模型服务换实现不动协议。</li><li><strong>Rust 编排器</strong>（ADR-002）：打断/取消/背压是并发问题，tokio CancellationToken 语义天然匹配。</li><li><strong>推理不重写</strong>：Python 调用现有推理库；Rust 只管编排与运维，不碰模型推理。</li><li><strong>降级只改 env</strong>（ADR-008）：同一套代码跑正常档/降级档。</li></ul><div class="tip custom-block"><p class="custom-block-title">完整版本</p><p><a href="https://github.com/Momoyeyu/momo-docs/blob/master/01-architecture/system.md" target="_blank" rel="noreferrer">momo-docs/01-architecture/system.md</a> · <a href="https://github.com/Momoyeyu/momo-docs/blob/master/01-architecture/boundaries.md" target="_blank" rel="noreferrer">boundaries.md</a> · <a href="https://github.com/Momoyeyu/momo-docs/blob/master/00-context/decisions.md" target="_blank" rel="noreferrer">decisions.md</a>（25 条 ADR）</p></div>',9))])}const _=d(c,[["render",s]]);export{b as __pageData,_ as default};
